CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY,first_name VARCHAR(255) NOT NULL,last_name VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,reset_token_hash VARCHAR(64) UNIQUE,reset_expires TIMESTAMP(6) NULL,created_at TIMESTAMP(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE products (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,description VARCHAR(255),price DECIMAL(10,2) NOT NULL,CHECK(price>=0)) ENGINE=InnoDB;
CREATE TABLE cart (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,product_id BIGINT NOT NULL,quantity INT NOT NULL,UNIQUE(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(quantity BETWEEN 1 AND 999)) ENGINE=InnoDB;
CREATE TABLE saved_addresses (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,kind VARCHAR(20) NOT NULL,address_line VARCHAR(255) NOT NULL,city VARCHAR(100) NOT NULL,state VARCHAR(100) NOT NULL,zip VARCHAR(20) NOT NULL,country VARCHAR(100) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),UNIQUE(user_id,kind,address_line,city,state,zip,country)) ENGINE=InnoDB;
CREATE TABLE demo_cards (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,card_number VARCHAR(20) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),UNIQUE(user_id,card_number)) ENGINE=InnoDB;
CREATE TABLE orders (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,address_id BIGINT NOT NULL,whitelist_address_id BIGINT NULL,delivery_address VARCHAR(700) NOT NULL,card_last_four VARCHAR(4),total DECIMAL(10,2) NOT NULL,submission_key VARCHAR(100) NOT NULL,submission_fingerprint VARCHAR(64) NOT NULL,deleted_at TIMESTAMP(6) NULL,created_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(address_id) REFERENCES saved_addresses(id),FOREIGN KEY(whitelist_address_id) REFERENCES saved_addresses(id),UNIQUE(user_id,submission_key),CHECK(total>=0)) ENGINE=InnoDB;
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,product_id BIGINT NOT NULL,product_name VARCHAR(255) NOT NULL,price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(quantity>0)) ENGINE=InnoDB;
CREATE TABLE order_tracking (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL UNIQUE,tracking_number VARCHAR(40) NOT NULL UNIQUE,status VARCHAR(50) NOT NULL,deleted_at TIMESTAMP(6) NULL,FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE legacy_imports (source_key VARCHAR(100) NOT NULL,table_name VARCHAR(40) NOT NULL,legacy_id BIGINT NOT NULL,target_id BIGINT NOT NULL,PRIMARY KEY(source_key,table_name,legacy_id)) ENGINE=InnoDB;
